<?php
declare(strict_types=1); namespace App\DataGrid\Repository; use App\DataGrid\Configuration\GridDefinition; use App\DataGrid\Contract\{GridRepositoryInterface,GridExportDataProviderInterface}; use App\DataGrid\Dto\{GridQuery,GridResult}; use Doctrine\ORM\{EntityManagerInterface,QueryBuilder}; use Symfony\Bundle\SecurityBundle\Security; abstract class AbstractDataTableRepository implements GridRepositoryInterface,GridExportDataProviderInterface {public function __construct(protected readonly EntityManagerInterface $em){} abstract protected function rootAlias():string; abstract protected function configureQueryBuilder(QueryBuilder $q,GridDefinition $d,Security $s):void; abstract protected function configureSelect(QueryBuilder $q,GridDefinition $d,Security $s):void; abstract protected function serializeRow(object $e,GridDefinition $d,Security $s):array; final protected function base(GridDefinition $d,Security $s):QueryBuilder{$q=$this->em->createQueryBuilder()->from($d->entityClass,$this->rootAlias());$this->configureQueryBuilder($q,$d,$s);$this->configureSelect($q,$d,$s);return$q;} public function search(GridDefinition $d,GridQuery $g,Security $s):GridResult{$d->assertGranted($s);$total=(int)(clone $this->base($d,$s))->select('COUNT('.$this->rootAlias().'.id)')->getQuery()->getSingleScalarResult();$q=$this->base($d,$s);foreach($g->filters as $i=>$f){$c=$d->column($f->columnId,$s);$p='f'.$i;if($f->operator->isLike()){$q->andWhere('LOWER('.$c->dqlExpression.') LIKE :'.$p)->setParameter($p,'%'.mb_strtolower((string)$f->value).'%');}elseif($f->operator->value==='between'){$q->andWhere($c->dqlExpression.' BETWEEN :'.$p.'a AND :'.$p.'b')->setParameter($p.'a',$f->value)->setParameter($p.'b',$f->secondValue);}else{$op=match($f->operator->value){'equals'=>'=','not_equals'=>'!=','gt'=>'>','lt'=>'<','gte'=>'>=','lte'=>'<=',default=>'='};$q->andWhere($c->dqlExpression.' '.$op.' :'.$p)->setParameter($p,$f->value);}}$filtered=(int)(clone $q)->select('COUNT('.$this->rootAlias().'.id)')->getQuery()->getSingleScalarResult();foreach($g->sorts as $x){$q->addOrderBy($d->column($x->columnId,$s)->dqlExpression,$x->direction->value);}$q->addOrderBy($this->rootAlias().'.id','ASC')->setFirstResult($g->page->offset())->setMaxResults($g->page->size);$rows=[];foreach($q->getQuery()->getResult() as $e)$rows[]=$this->serializeRow($e,$d,$s);return new GridResult($rows,$total,$filtered,$g->page->number,$g->page->size);} public function iterateGridRows(GridDefinition $d,GridQuery $g,Security $s,int $n=500):\Generator{for($p=1;;++$p){$r=$this->search($d,new GridQuery(new \App\DataGrid\Dto\GridPage($p,$n),$g->filters,$g->sorts,$g->globalSearch),$s);foreach($r->rows as $row)yield$row;if($p*$n>=$r->filteredTotal)break;$this->em->clear();}}}
